CREATE TABLE sub13_cte_sales (sale_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, amount INTEGER NOT NULL);
INSERT INTO sub13_cte_sales VALUES (1, 'Asha', 50), (2, 'Asha', 70), (3, 'Bilal', 40), (4, 'Mira', 30);
WITH customer_totals AS (SELECT customer, SUM(amount) AS total_amount FROM sub13_cte_sales GROUP BY customer)
SELECT customer, total_amount FROM customer_totals ORDER BY customer;

